import { Readable } from 'stream';

export default class PDFDocument extends Readable {
  constructor(options = {}) {
    super();
    this.options = options;
    this.buffer = [];
    this.lines = [];
    this.currentFontSize = 12;
    this.currentFillColor = '#000000';
    this.x = 50;
    this.y = 50;
  }

  _read() {}

  fillColor(color) {
    this.currentFillColor = color;
    return this;
  }

  fontSize(size) {
    this.currentFontSize = size;
    return this;
  }

  text(str, x, y, opts) {
    const textStr = String(str || '');
    this.lines.push({ text: textStr, x: x || this.x, y: y || this.y, size: this.currentFontSize, color: this.currentFillColor });
    return this;
  }

  moveDown(n = 1) {
    this.y += n * (this.currentFontSize + 4);
    return this;
  }

  moveTo(x, y) {
    this.pathStart = { x, y };
    return this;
  }

  lineTo(x, y) {
    this.pathEnd = { x, y };
    return this;
  }

  strokeColor(c) {
    return this;
  }

  lineWidth(w) {
    return this;
  }

  stroke() {
    return this;
  }

  pipe(destination, options) {
    return super.pipe(destination, options);
  }

  end() {
    // Generate valid minimalist PDF 1.4
    const contentStream = this.lines
      .map(
        (l, i) =>
          `BT /F1 ${Math.round(l.size)} Tf ${Math.round(l.x)} ${Math.round(792 - (l.y || 50 + i * 18))} Td (${l.text.replace(/[()]/g, '')}) Tj ET`
      )
      .join('\n');

    const streamLength = Buffer.byteLength(contentStream);

    const pdfParts = [
      '%PDF-1.4',
      '1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj',
      '2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 >> endobj',
      '3 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >> endobj',
      `4 0 obj << /Length ${streamLength} >> stream\n${contentStream}\nendstream\nendobj`,
      '5 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> endobj',
      'xref',
      '0 6',
      '0000000000 65535 f ',
      '0000000009 00000 n ',
      '0000000058 00000 n ',
      '0000000115 00000 n ',
      '0000000244 00000 n ',
      '0000000300 00000 n ',
      'trailer << /Size 6 /Root 1 0 R >>',
      'startxref',
      '360',
      '%%EOF'
    ];

    const pdfData = Buffer.from(pdfParts.join('\n'));
    this.push(pdfData);
    this.push(null);
  }
}
